def main_html(d, related):
    steps=''.join(f'<article class="step"><span class="step-num">{i:02d}</span><h3>{t}</h3><p>{p}</p></article>' for i,(t,p) in enumerate(d['steps'],1))
    comps=''.join(f'<article class="compare-card{(" highlight" if i==0 else "")}"><h3>{t}</h3><ul>'+''.join(f'<li>{x}</li>' for x in lis)+'</ul></article>' for i,(t,lis) in enumerate(d['compare']))
    facts=''.join(f'<article class="fact-card"><h3>{t}</h3><p>{p}</p></article>' for t,p in d['facts'])
    faqs=''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in d['faq'])
    rel=''.join(f'<a href="{u}">{n}</a>' for n,u in related)
    clinic=''.join(f'<p>{p}</p>' for p in d['clinic_ps'])
    return f'''<main>
<section class="hero"><div class="wrap"><div class="crumb"><a href="/">Accueil</a> / <a href="/#soins">Nos soins</a> / {d['crumb']}</div><span class="pill">{d['eyebrow']}</span><h1>{d['h1']} <span>à Tanger</span></h1><p>{d['lead']}</p><div class="actions"><a class="btn btn-primary" href="tel:+212531112127">Appeler le cabinet</a><a class="btn btn-secondary" href="https://wa.me/212771158018" target="_blank" rel="noopener">WhatsApp</a></div></div></section>
<section class="section"><div class="inner content-grid"><div><div class="section-head"><span class="kicker">{d['under_k']}</span><h2>{d['under_h']}</h2><p class="lead">{d['under_lead']}</p></div><p>{d['under_p']}</p><h3>{d['under_h3a']}</h3><p>{d['under_pa']}</p><h3>{d['under_h3b']}</h3><p>{d['under_pb']}</p></div><aside class="note"><b>{d['note_b']}</b><p>{d['note_p']}</p></aside></div></section>
<section class="section alt"><div class="inner"><div class="section-head"><span class="kicker">Les étapes</span><h2>{d['steps_h']}</h2><p class="lead">{d['steps_lead']}</p></div><div class="steps">{steps}</div></div></section>
<section class="section"><div class="inner"><div class="section-head"><span class="kicker">{d['compare_k']}</span><h2>{d['compare_h']}</h2><p class="lead">{d['compare_lead']}</p></div><div class="compare">{comps}</div></div></section>
<section class="section alt"><div class="inner"><div class="section-head"><span class="kicker">Questions pratiques</span><h2>{d['facts_h']}</h2></div><div class="facts-grid">{facts}</div></div></section>
<section class="section"><div class="inner content-grid"><div><div class="section-head"><span class="kicker">Votre prise en charge à Tanger</span><h2>{d['clinic_h']}</h2></div>{clinic}</div><aside class="note"><b>{d['clinic_note_b']}</b><p>{d['clinic_note_p']}</p></aside></div></section>
<section class="section alt"><div class="inner faq"><div class="section-head"><span class="kicker">{d['faq_k']}</span><h2>{d['faq_h']}</h2></div>{faqs}</div></section>
<section class="section alt"><div class="inner"><div class="section-head"><span class="kicker">Soins associés</span><h2>Découvrir les autres <span class="accent">soins dentaires</span></h2><p class="lead">Selon votre situation, ce traitement peut s’inscrire dans une prise en charge plus globale.</p></div><div class="related-care">{rel}</div></div></section>
<section class="section" id="contact"><div class="inner"><div class="local-card"><div class="local-copy"><span class="kicker">Centre Dentaire Venezuela</span><h2>{d['contact_h']}</h2><p>{d['contact_p']}</p><div class="local-actions"><a class="btn btn-primary" href="tel:+212531112127">+212 5 31 11 21 27</a><a class="btn btn-secondary" href="https://wa.me/212771158018" target="_blank" rel="noopener">Ouvrir WhatsApp</a></div></div><div class="local-info"><div class="local-row"><small>Adresse</small><b>4ème étage n°74, Immeuble Venezuela<br>89 Rue Moussa Ben Noussair<br>Tanger 90000, Maroc</b></div><div class="local-row"><small>Google Maps</small><a href="https://share.google/NQdfjEYv9MC4431Lz" target="_blank" rel="noopener">Voir l’itinéraire →</a></div><div class="local-row"><small>Email</small><a href="mailto:centredentairevenezuela@gmail.com">centredentairevenezuela@gmail.com</a></div><div class="local-row"><small>Instagram</small><a href="https://www.instagram.com/centre.dentaire.venezuela/" target="_blank" rel="noopener">@centre.dentaire.venezuela</a></div></div></div></div></section>
</main>'''

for path_str,d in PAGES.items():
    path=Path(path_str)
    text=path.read_text(encoding='utf-8')
    if '/* Expanded service page sections — aligned with implant page */' not in text:
        text=text.replace('</style>',CSS+'\n</style>',1)
    new_main=main_html(d,RELATED[path_str])
    text,n=re.subn(r'<main>.*?</main>',new_main,text,count=1,flags=re.S)
    if n!=1: raise RuntimeError(f'Expected one main in {path}')
    path.write_text(text,encoding='utf-8')
    print('Expanded',path)

